#!/usr/bin/env python3
"""Replace NEW-<rung>-<n> placeholders by ledger row numbers in the named files.

usage: placeholders.py MAP FILE...   MAP like NEW-X-1=773,NEW-X-2=774
'row NEW-X-1' -> 'row 773'; 'row~NEW-X-1' -> 'row~773'; "NEW-X-2's row" -> 'row 774';
a bare placeholder -> 'row 773' ('Row 773' where a sentence, item or cell opens).
"""
import re, sys

mapping = dict(kv.split('=') for kv in sys.argv[1].split(','))
pat = re.compile(r'(?P<pre>(?:\b[Rr]ows?[ ~]|\b[Rr]ows? ))?(?P<ph>NEW-[A-Z]-\d+)(?P<post>\'s row\b)?')

def fix(text):
    out, last = [], 0
    for m in pat.finditer(text):
        ph = m.group('ph')
        if ph not in mapping:
            continue
        num = mapping[ph]
        out.append(text[last:m.start()])
        if m.group('pre'):
            out.append(m.group('pre') + num)
        else:
            before = text[:m.start()]
            opens = (before == '' or re.search(r'(^|\n)\s*$|(^|\n)\s*[-*|]\s*$|[.!?]\s+$|\|\s*$|\*\*$|^\s*\d+\.\s*$', before[-6:] if len(before) >= 6 else before) is not None
                     or re.search(r'(\n|^)(\s*([-*]|\d+\.)?\s*)$', before) is not None
                     or re.search(r'[.!?]\s+$', before) is not None
                     or re.search(r'\|\s+$', before) is not None)
            out.append(('Row ' if opens else 'row ') + num)
            if m.group('post'):
                # "NEW-X-2's row" -> "row 774"
                pass
        last = m.end()
    out.append(text[last:])
    return ''.join(out)

for path in sys.argv[2:]:
    with open(path, encoding='utf-8') as f:
        old = f.read()
    new = fix(old)
    if new != old:
        with open(path, 'w', encoding='utf-8') as f:
            f.write(new)
        print(path, 'changed')
left = []
for path in sys.argv[2:]:
    with open(path, encoding='utf-8') as f:
        for i, line in enumerate(f, 1):
            for ph in re.findall(r'NEW-[A-Z]-\d+', line):
                if ph in mapping:
                    left.append(f'{path}:{i}: {ph}')
print('\n'.join(left) if left else 'no mapped placeholder left')

